sn_aia_tool.script:
(function(inputs) {
    var assetList = [];
    var identityAssetGr = new GlideRecordSecure('x_aleen_snguardian_identity_asset');
    identityAssetGr.addQuery('identity', inputs.identity_id);
    identityAssetGr.addQuery('status.code', 'ACTIVE');
    identityAssetGr.addQuery("provisioning_status.code=success^ORprovisioning_status.codeLIKEupdate-success");
    identityAssetGr.query();
    while (identityAssetGr.next()) {
        var assObj = {};
        assObj.serial = identityAssetGr.getDisplayValue('asset.serial');
        assObj.asset = identityAssetGr.getValue('asset');
        assObj.status = identityAssetGr.getValue('status');
        assObj.status_value = identityAssetGr.getDisplayValue('status');
        assObj.type_value = identityAssetGr.getDisplayValue('asset.type.description');
        assObj.type = identityAssetGr.getValue('status');
        assObj.id = identityAssetGr.getValue('sys_id');
        assetList.push(assObj);
    }
    gs.info(JSON.stringify(assetList));
    return assetList;
})(inputs);
